/* ---------- 工具函数 ---------- */

function loadFromStorage(): ICategory[] {
  try {
    const raw = scopedStorage.getItem(STORAGE_KEY);
    if (!raw) return [];
    const parsed = JSON.parse(raw);
    if (!Array.isArray(parsed)) return [];
    return parsed.map((item) => ({
      id: String(item.id ?? ''),
      slug: String(item.slug ?? ''),
      name: migrateI18n(item.name),
      description: migrateI18n(item.description),
       icon: String(item.icon ?? ''),
       iconImage: item.iconImage ? String(item.iconImage) : undefined,
       sortOrder: Number(item.sortOrder ?? 0),
      enabled: Boolean(item.enabled ?? true),
      createdAt: Number(item.createdAt ?? Date.now()),
    }));
  } catch {
    return [];
  }
}

function saveToStorage(list: ICategory[]) {
  try {
    scopedStorage.setItem(STORAGE_KEY, JSON.stringify(list));
  } catch {
    // ignore
  }
}

function sortCategories(list: ICategory[]): ICategory[] {
  return [...list].sort((a, b) => a.sortOrder - b.sortOrder || a.createdAt - b.createdAt);
}

/* ---------- Hook ---------- */

let initialized = false;
// 🔴 模块加载时同步初始化：从 localStorage 读取，没有就用默认数据
// 这样首次渲染时 storeCategories 就有数据，不会出现空数组闪烁
let storeCategories: ICategory[] = (() => {
  try {
    const raw = scopedStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      if (Array.isArray(parsed) && parsed.length > 0) {
        const mapped = parsed.map((item) => ({
          id: String(item.id ?? ''),
          slug: String(item.slug ?? ''),
          name: migrateI18n(item.name),
          description: migrateI18n(item.description),
          icon: String(item.icon ?? ''),
          iconImage: item.iconImage ? String(item.iconImage) : undefined,
          sortOrder: Number(item.sortOrder ?? 0),
          enabled: Boolean(item.enabled ?? true),
          createdAt: Number(item.createdAt ?? Date.now()),
        }));
        return sortCategories(mapped);
      }
    }
  } catch {
    // ignore
  }
  return DEFAULT_CATEGORIES;
})();
const subscribers = new Set<(list: ICategory[]) => void>();

function broadcast() {
  subscribers.forEach((fn) => fn(storeCategories));
}

/**
 * 从 localStorage 重新加载分类数据（GitHub 拉取完成后调用）
 */
export function refreshCategoriesStore(): void {
  try {
    const raw = scopedStorage.getItem(STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      const data = Array.isArray(parsed) ? parsed : parsed.data;
      if (Array.isArray(data) && data.length > 0) {
        const mapped = data.map((item: Record<string, unknown>) => ({
          id: String(item.id ?? ''),
          slug: String(item.slug ?? ''),
          name: migrateI18n(item.name as string | I18nText | undefined),
          description: migrateI18n(item.description as string | I18nText | undefined),
          icon: String(item.icon ?? ''),
          iconImage: item.iconImage ? String(item.iconImage) : undefined,
          sortOrder: Number(item.sortOrder ?? 0),
          enabled: Boolean(item.enabled ?? true),
          createdAt: Number(item.createdAt ?? Date.now()),
        }));
        storeCategories = sortCategories(mapped);
        broadcast();
        logger.info(`[Categories] Refreshed ${mapped.length} categories from localStorage (GitHub pull)`);
        return;
      }
    }
    logger.warn('[Categories] No data in localStorage after GitHub pull');
  } catch (err) {
    logger.error('[Categories] Failed to refresh from localStorage:', String(err));
  }
}

export function useCategories(options?: { preferRemote?: boolean }) {
  const preferRemote = options?.preferRemote ?? false;
  const remoteData = useRemoteDataStore<ICategory[]>('categories');
  const [categories, setCategories] = useState<ICategory[]>(storeCategories);

  useEffect(() => {
    const handler = (next: ICategory[]) => setCategories(next);
    subscribers.add(handler);

    // 首次初始化：处理迁移/持久化等副作用（数据同步初始化已在模块级完成）
    if (!initialized) {
      initialized = true;
      // 确保 localStorage 中有数据（空的话写入默认值）
      const list = loadFromStorage();
      if (list.length === 0) {
        saveToStorage(storeCategories);
      }
      broadcast();
    } else {
      setCategories(storeCategories);
    }

    return () => {
      subscribers.delete(handler);
    };
  }, []);

  const saveCategories = useCallback((items: ICategory[]) => {
    const sorted = sortCategories(items);
    storeCategories = sorted;
    saveToStorage(sorted);
    broadcast();
  }, []);

  const addCategory = useCallback(
    (data: Omit<ICategory, 'id' | 'createdAt' | 'sortOrder'> & { sortOrder?: number }): ICategory => {
      const id = `cat_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`;
      const sortOrder =
        typeof data.sortOrder === 'number' && Number.isFinite(data.sortOrder)
          ? data.sortOrder
          : storeCategories.length + 1;
      const newCat: ICategory = {
        ...data,
        id,
        sortOrder,
        createdAt: Date.now(),
      };
      storeCategories = sortCategories([...storeCategories, newCat]);
      saveToStorage(storeCategories);
      broadcast();
      return newCat;
    },
    [],
  );

  const updateCategory = useCallback((id: string, data: Partial<Omit<ICategory, 'id' | 'createdAt'>>) => {
    const idx = storeCategories.findIndex((c) => c.id === id);
    if (idx === -1) return null;
    const updated: ICategory = { ...storeCategories[idx], ...data };
    storeCategories = sortCategories([
      ...storeCategories.slice(0, idx),
      updated,
      ...storeCategories.slice(idx + 1),
    ]);
    saveToStorage(storeCategories);
    broadcast();
    return updated;
  }, []);

  const deleteCategory = useCallback((id: string) => {
    storeCategories = storeCategories.filter((c) => c.id !== id);
    // 重排序号
    storeCategories = storeCategories.map((c, i) => ({ ...c, sortOrder: i + 1 }));
    saveToStorage(storeCategories);
    broadcast();
  }, []);

  const moveCategory = useCallback((id: string, direction: 'up' | 'down') => {
    const sorted = sortCategories(storeCategories);
    const idx = sorted.findIndex((c) => c.id === id);
    if (idx === -1) return;
    const targetIdx = direction === 'up' ? idx - 1 : idx + 1;
    if (targetIdx < 0 || targetIdx >= sorted.length) return;
    const currentOrder = sorted[idx].sortOrder;
    const targetOrder = sorted[targetIdx].sortOrder;
    storeCategories = sorted.map((c) => {
      if (c.id === id) return { ...c, sortOrder: targetOrder };
      if (c.id === sorted[targetIdx].id) return { ...c, sortOrder: currentOrder };
      return c;
    });
    storeCategories = sortCategories(storeCategories);
    saveToStorage(storeCategories);
    broadcast();
  }, []);

  const getCategoryBySlug = useCallback(
    (slug: string): ICategory | undefined => {
      return storeCategories.find((c) => c.slug === slug);
    },
    [],
  );

  /** 最终展示的类目数据：优先远程 */
  const displayCategories = useMemo(() => {
    if (preferRemote && remoteData && Array.isArray(remoteData) && remoteData.length > 0) {
      const transformed = safeTransform('categories', () =>
        remoteData.map((raw: unknown, idx: number) => {
          const c = (raw ?? {}) as Record<string, unknown>;
          return {
            id: safeStr(c.id, `cat_remote_${idx}`),
            name: safeI18n(c.name),
            slug: safeStr(c.slug, `category-${idx}`),
            description: safeI18n(c.description),
            icon: safeStr(c.icon, 'Tag'),
            sortOrder: safeNum(c.sortOrder ?? c.order, idx + 1),
            enabled: safeBool(c.enabled, true),
            parentId: safeStr(c.parentId, ''),
            createdAt: safeNum(c.createdAt, Date.now()),
          } as unknown as ICategory;
        })
      );
      if (transformed && transformed.length > 0) {
        return transformed.sort((a, b) => a.sortOrder - b.sortOrder);
      }
      logger.warn('[Categories] remote data transform failed or empty, falling back to local');
    }
    return categories;
  }, [preferRemote, remoteData, categories]);

  /** 仅启用的类目（前台用） */
  const enabledCategories = useMemo(
    () => displayCategories.filter((c) => c.enabled),
    [displayCategories],
  );

  /** slug → 类目映射表（方便快速查找） */
  const slugMap = useMemo(() => {
    const map: Record<string, ICategory> = {};
    displayCategories.forEach((c) => {
      map[c.slug] = c;
    });
    return map;
  }, [displayCategories]);

  return {
    categories: displayCategories,
    enabledCategories,
    slugMap,
    addCategory,
    updateCategory,
    deleteCategory,
    moveCategory,
    getCategoryBySlug,
    saveCategories,
    isUsingRemoteData: preferRemote && !!remoteData,
  };
}
